open class Actor {
    var x = 0
    var y = 0
    var rotation = 0
    var image = Image("")
    var worldWidth = 0
    var worldHeight = 0
    fun setImage(path: String) { image = Image(path) }
    fun setImage(newImage: Image) { image = newImage }
    fun getImage(): Image = image
    fun getX(): Int = x
    fun getY(): Int = y
    fun setLocation(newX: Int, newY: Int) { x = newX; y = newY }
    fun getRotation(): Int = rotation
    fun setRotation(degrees: Int) { rotation = degrees }
    open fun act() {}
    fun move(distance: Int) {
        val normalized = ((rotation % 360) + 360) % 360
        if (normalized == 90) y += distance
        else if (normalized == 180) x -= distance
        else if (normalized == 270) y -= distance
        else x += distance
    }
    fun turn(degrees: Int) { rotation += degrees }
    val isAtEdge: Boolean get() = worldWidth > 0 && worldHeight > 0 && (x <= 0 || y <= 0 || x >= worldWidth - 1 || y >= worldHeight - 1)
    val isClicked: Boolean get() = bluekIsActorClicked(x, y)
}

fun bluekEscape(value: String): String {
    var escaped = ""
    var index = 0
    while (index < value.length) {
        val character = value.substring(index, index + 1)
        if (character == "\"") escaped += "\\\""
        else if (character == "\\") escaped += "\\\\"
        else if (character == "\n") escaped += "\\n"
        else escaped += character
        index += 1
    }
    return escaped
}

open class World(val width: Int, val height: Int, val cellSize: Int = 1) {
    private val actors = mutableListOf<Actor>()
    private val textX = mutableListOf<Int>()
    private val textY = mutableListOf<Int>()
    private val textValues = mutableListOf<String>()
    var backgroundColor = "rgb(255,255,255)"
    var background = Image("")
    var running = false
    var speed = 50
    fun actorType(actor: Actor): String = "Actor"
    fun render() {
        var objects = "["
        var first = true
        for (current in actors) {
            if (!first) objects += ","
            first = false
            val imagePath = current.image.path
            objects += "{\"type\":\"${actorType(current)}\",\"x\":${current.x},\"y\":${current.y},\"rotation\":${current.rotation},\"imagePath\":\"${bluekEscape(imagePath)}\"}"
        }
        objects += "]"
        val backgroundPath = background.path
        var texts = "["
        var textFirst = true
        var textIndex = 0
        while (textIndex < textValues.size) {
            if (!textFirst) texts += ","
            textFirst = false
            texts += "{\"x\":${textX[textIndex]},\"y\":${textY[textIndex]},\"text\":\"${bluekEscape(textValues[textIndex])}\"}"
            textIndex += 1
        }
        texts += "]"
        bluekStageUpdate("{\"stage\":{\"width\":${width},\"height\":${height},\"cellSize\":${cellSize},\"backgroundColor\":\"${bluekEscape(backgroundColor)}\",\"backgroundPath\":\"${bluekEscape(backgroundPath)}\",\"speed\":${speed},\"running\":${running},\"objects\":${objects},\"texts\":${texts}}}")
    }
    fun show() { render() }
    fun getWidth(): Int = width
    fun getHeight(): Int = height
    fun getCellSize(): Int = cellSize
    fun setBackground(fileName: String) { background = Image(fileName); show() }
    fun setBackground(red: Int, green: Int, blue: Int) {
        backgroundColor = "rgb(${red},${green},${blue})"
        background = Image("")
        show()
    }
    fun showText(text: String, x: Int, y: Int) {
        var index = 0
        while (index < textValues.size) {
            if (textX[index] == x && textY[index] == y) {
                if (text.isEmpty()) {
                    textX.removeAt(index)
                    textY.removeAt(index)
                    textValues.removeAt(index)
                } else {
                    textValues[index] = text
                }
                show()
                return
            }
            index += 1
        }
        if (text.isNotEmpty()) {
            textX.add(x)
            textY.add(y)
            textValues.add(text)
        }
        show()
    }
    open fun act() {}
    fun tick() { act(); for (current in actors) current.act() }
    fun addObject(actor: Actor, x: Int, y: Int) {
        if (actors.count { it == actor } == 0) {
            actors.add(actor)
        }
        actor.worldWidth = width
        actor.worldHeight = height
        actor.x = x
        actor.y = y
    }
    fun removeObject(actor: Actor) {
        if (actors.count { it == actor } > 0) {
            actors.remove(actor)
        }
    }
    fun allObjects(): List<Actor> = actors
    fun getObjectsAt(x: Int, y: Int): List<Actor> = actors.filter { it.x == x && it.y == y }
    val numberOfObjects: Int get() = actors.size
    val isClicked: Boolean get() = bluekIsWorldClicked()
}

// Browser-only BluePlay bridge. The visible world is rendered by BlueK.
var currentWorld: World?
fun activeWorld(): World = currentWorld as World
fun isKeyDown(key: String): Boolean = bluekIsKeyDown(key)
fun showWorld(world: World) { currentWorld = world; world.show() }
fun show() { showWorld(activeWorld()) }
fun start() { activeWorld().running = true; activeWorld().show() }
fun stop() { activeWorld().running = false; activeWorld().show() }
fun step() { activeWorld().tick(); activeWorld().show() }
fun setSpeed(value: Int) { activeWorld().speed = if (value < 1) 1 else if (value > 100) 100 else value; activeWorld().show() }
fun getSpeed(): Int = activeWorld().speed
fun playSound(fileName: String) { bluekPlaySound(fileName) }

/**
 * A simple figure that slowly walks to the right.
 */
class Figure : Actor() {

    override fun act() {
        // Explicit receiver is required by the current Kotlite superclass
        // member lookup for this first browser-only BluePlay example.
        this.move(1)
    }
}

/**
 * A minimal world. It places a figure when it is created.
 */
class MyWorld : World(600, 400, 1) {
    var initialized = false

    init {
        initialized = true
    }
}

/**
 * Minimal BluePlay example.
 * In BlueJ: right-click 'Main' -> main() to load the world, then press Run.
 * The Reset button in the window runs this main() again.
 */
fun main() {
    val world = MyWorld()
    world.addObject(Figure(), 100, 200)
    showWorld(world)
}
